def find_duplicates(data: List[int]) -> List[int]:
    """Find duplicate values in a list of integers efficiently."""
    duplicates = set()
    for i in range(len(data) - 1):
        if data[i] == data[i + 1]:
            if data[i] not in duplicates:
                duplicates.add(data[i])
    return sorted(duplicates)
